window.onkeydown=e=>{if(e.key==='Escape'&&playing){e.preventDefault();abortMatch();return}if(!playing)return;const k=e.key.toLowerCase();if(['arrowleft','arrowright','arrowup',' '].includes(k))e.preventDefault();if(k==='a'||(!localTwoPlayer&&k==='arrowleft'))keys.left=true;if(k==='d'||(!localTwoPlayer&&k==='arrowright'))keys.right=true;if(k==='w'||(!localTwoPlayer&&k==='arrowup'))keys.jump=true;if(localTwoPlayer&&k==='arrowleft')keys.p2left=true;if(localTwoPlayer&&k==='arrowright')keys.p2right=true;if(localTwoPlayer&&k==='i')keys.p2jump=true;if(localTwoPlayer&&k==='1')keys.p2light=true;if(localTwoPlayer&&k==='2')keys.p2heavy=true;if(localTwoPlayer&&k==='3')keys.p2special=true;if(localTwoPlayer&&k==='0')keys.p2super=true;if(localTwoPlayer&&k==='shift')keys.p2block=true;if(k===' ')keys.block=true;if(k==='j')keys.light=true;if(k==='k')keys.heavy=true;if(k==='l')keys.special=true;if(k==='u'||k==='enter')keys.super=true};
